def _object(name, mesh, coll, material, cap, bs):
    ob = bs.bpy.data.objects.new(name, mesh)
    coll.objects.link(ob)
    if material:
        mesh.materials.append(material)
    ob.parent = cap
    ob.matrix_parent_inverse = bs.Matrix.Identity(4)
    return ob


